```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Comparison of feature profiles between Brás and the top 5 most similar Chicago areas",
  "transform": [
    {
      "fold": [
        "poverty_rate",
        "unemployment_rate",
        "median_income",
        "edu_low",
        "minority_pct",
        "housing_burden",
        "crash_rate",
        "pop_density",
        "transit_access",
        "access_score"
      ],
      "as": ["feature", "value"]
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "feature",
      "type": "nominal",
      "axis": {"labelAngle": -45},
      "title": "Urban Indicator"
    },
    "y": {
      "field": "value",
      "type": "quantitative",
      "title": "Normalized Value"
    },
    "color": {
      "field": "area_name",
      "type": "nominal",
      "title": "Area Name"
    },
    "column": {
      "field": "area_name",
      "type": "nominal",
      "title": "Areas Comparison"
    },
    "opacity": {
      "condition": {
        "test": "datum.interacted === '1'",
        "value": 1
      },
      "value": 0.7
    }
  },
  "config": {
    "view": {"stroke": "transparent"},
    "facet": {"spacing": 10}
  }
}
```
